import React from 'react';
import { useNavigate } from 'react-router-dom';

function CartPage({ cart, onClearCart }) {
    const navigate = useNavigate();

    const handlePlaceOrder = async () => {
        const token = localStorage.getItem('token'); // Retrieve token from storage
        const products = cart.map((item) => ({
            product: item.id, // Product ID
            quantity: item.quantity, // Quantity
            price: item.price, // Price per product
        }));
        const totalAmount = cart.reduce((sum, item) => sum + item.price * item.quantity, 0); // Total amount

        try {
            const response = await fetch('/api/orders', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    Authorization: `Bearer ${token}`, // Include the token
                },
                body: JSON.stringify({ products, totalAmount }), // Send order data
            });

            if (!response.ok) {
                const errorData = await response.json();
                throw new Error(errorData.message || 'Failed to place order.');
            }

            const orderData = await response.json();
            alert('Order placed successfully!');
            onClearCart(); // Clear the cart after placing the order
            navigate('/orders'); // Redirect to Orders page
        } catch (error) {
            alert(error.message);
        }
    };

    return (
        <div className="cart-page">
            <h1>Your Cart</h1>
            {cart.length === 0 ? (
                <p>Your cart is empty.</p>
            ) : (
                <>
                    <ul>
                        {cart.map((item) => (
                            <li key={item.id}>
                                {item.name} - ${item.price} (x{item.quantity})
                            </li>
                        ))}
                    </ul>
                    <h2>Total: ${cart.reduce((sum, item) => sum + item.price * item.quantity, 0).toFixed(2)}</h2>
                    <button onClick={handlePlaceOrder}>Place Order</button>
                </>
            )}
        </div>
    );
}

export default CartPage;
